"""Summarize mailbox letters without modifying the input tree."""
import argparse
from datetime import datetime, timedelta
import json
from pathlib import Path
import re
import sys


NAME = re.compile(r"^\d{8}T\d{4}[-_]")
RESOLVING = {"DONE", "BLOCKED", "NEEDS-USER", "FAILED"}


def read_letter(path, now):
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except (OSError, UnicodeError):
        return None, "no_frontmatter"
    if not lines or lines[0] != "---":
        return None, "no_frontmatter"
    try:
        end = lines.index("---", 1)
    except ValueError:
        return None, "no_frontmatter"
    fields = {}
    for line in lines[1:end]:
        if ": " in line:
            key, value = line.split(": ", 1)
            fields[key] = value
    if any(not fields.get(key) for key in ("id", "from", "to", "status", "at")):
        return None, "no_field"
    try:
        at = datetime.fromisoformat(fields["at"])
    except ValueError:
        return None, "no_field"
    if at.tzinfo is None:
        at = at.replace(tzinfo=now.tzinfo)
    if not NAME.match(path.name):
        return None, "bad_name"
    try:
        datetime.strptime(path.name[:13], "%Y%m%dT%H%M")
    except ValueError:
        return None, "bad_name"
    return {"id": fields["id"], "from": fields["from"],
            "to": fields["to"], "status": fields["status"],
            "at": at, "re": fields.get("re", "")}, None


def summarize(root, now):
    boxes = {}
    candidates = []
    for mailbox in sorted(root.iterdir(), key=lambda path: path.name):
        if mailbox.name.startswith(".") or mailbox.is_symlink() or not mailbox.is_dir():
            continue
        inbox = mailbox / "inbox"
        if inbox.is_symlink() or not inbox.is_dir():
            continue
        boxes[mailbox.name] = {"inbox": {}, "done": 0}
        for directory, where in ((inbox, "inbox"), (inbox / "done", "done")):
            if directory.is_symlink() or not directory.is_dir():
                continue
            for path in directory.iterdir():
                if (path.name.startswith(".") or path.suffix != ".md"
                        or path.is_symlink() or not path.is_file()):
                    continue
                candidates.append((path.relative_to(root).as_posix(), path, where, mailbox.name))

    bad = []
    valid = []
    seen = set()
    for relative, path, where, mailbox in sorted(candidates, key=lambda item: item[0]):
        letter, why = read_letter(path, now)
        if why is None and letter["id"] in seen:
            why = "dup_id"
        if why is not None:
            bad.append({"file": relative, "why": why})
            continue
        seen.add(letter["id"])
        letter["where"] = where
        valid.append(letter)
        if where == "inbox":
            counts = boxes[mailbox]["inbox"]
            counts[letter["status"]] = counts.get(letter["status"], 0) + 1
        else:
            boxes[mailbox]["done"] += 1

    resolved = {letter["re"] for letter in valid
                if letter["re"] and letter["status"] in RESOLVING}
    open_letters = []
    for letter in valid:
        if letter["status"] == "REQUEST" and letter["id"] not in resolved:
            open_letters.append({
                "id": letter["id"], "from": letter["from"],
                "to": letter["to"], "where": letter["where"],
                "age_min": (now - letter["at"]) // timedelta(minutes=1),
            })
    open_letters.sort(key=lambda letter: (letter["to"], letter["id"]))
    return {"v": 1, "open": open_letters, "boxes": boxes, "bad": bad}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only mailbox todo summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO timestamp with a timezone")
    if now.tzinfo is None:
        parser.error("--now must include a timezone")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    try:
        result = summarize(args.folder, now)
    except OSError as error:
        parser.error(str(error))
    print(json.dumps(result, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
